void mainImage(out vec4 O, vec2 C)
{
    O-=O;
	vec2 q=C.xy/iResolution.y-0.5;
       q.x-=0.3;
    vec3 p,d=normalize(vec3(q,-0.-dot(q,q)*2.)).xzy;

    d.xz+=sin(d.xz*5.)*12.;
   d.z-=5.5;

    float t,e,i;
    for(i=0.;i<30.;i++){
        p=d*t;

          p.x+=iTime*10.;
        t+=e=(length(vec3(mod(p.xz,4.)-2.,p.y+2.)))*.05;
    }
    O=vec4(cos(vec3(5,7,9)+d)/30./e,1);
}
